import json
p=".post/ROLE-STDOUT.raw"
for i,line in enumerate(open(p,encoding="utf-8"),1):
    line=line.strip()
    if not line: continue
    if i==1:
        print("LINE1:",line); continue
    try: o=json.loads(line)
    except Exception as e:
        print("nonjson line",i,repr(line[:120])); continue
    t=o.get("type")
    if t=="item.started" or t=="item.completed":
        it=o.get("item",{})
        typ=it.get("type")
        if typ=="command_execution":
            print("="*72)
            print("CMD",it.get("id"),"status",it.get("status"),"exit",it.get("exit_code"))
            print("CMDSTR:",it.get("command","")[:700])
            ao=it.get("aggregated_output","") or ""
            print("OUTLEN:",len(ao))
        elif typ=="file_change":
            print("="*72)
            print("FILECHANGE",it.get("id"),it.get("status"),json.dumps(it.get("changes"),ensure_ascii=False))
    elif t=="thread.started":
        print("THREAD:",o.get("thread_id"))
    elif t=="turn.completed":
        print("TURN COMPLETED usage:",json.dumps(o.get("usage")))
PY

